const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    this.window = new Window();
    this.document = this.window.document;
    this.document.open();
    const templatePath = path.resolve(__dirname, '../../assets/app-template.index.html');
    const html = fs.readFileSync(templatePath, 'utf8');
    this.document.write(html);
    this.document.close();

    // Load todomvc-common/base.js if it exists
    const basePath = path.resolve(__dirname, '../../node_modules/todomvc-common/base.js');
    if (fs.existsSync(basePath)) {
      const baseScript = this.document.createElement('script');
      baseScript.textContent = fs.readFileSync(basePath, 'utf8');
      this.document.body.appendChild(baseScript);
    }

    // Load the app
    const appPath = path.resolve(__dirname, '../../js/app.js');
    if (fs.existsSync(appPath)) {
      const appScript = this.document.createElement('script');
      appScript.textContent = fs.readFileSync(appPath, 'utf8');
      this.document.body.appendChild(appScript);
    }
  }

  async reloadPage() {
    const html = this.document.documentElement.outerHTML;
    this.window = new Window();
    this.document = this.window.document;
    this.document.open();
    this.document.write('<!DOCTYPE html>\n' + html);
    this.document.close();
  }

  find(selector) {
    return this.document.querySelector(selector);
  }

  findAll(selector) {
    return Array.from(this.document.querySelectorAll(selector));
  }

  async createTodo(title) {
    const input = this.find('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
  }

  async createCompletedTodo(title) {
    await this.createTodo(title);
    const toggle = this.find('.todo-list li:last-child .toggle');
    toggle.click();
  }

  sendEnter(element) {
    element.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
  }

  sendEscape(element) {
    element.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27 }));
  }

  async destroyTodo(title) {
    const todos = this.findAll('.todo-list li');
    for (const todo of todos) {
      const label = todo.querySelector('label');
      if (label && label.textContent === title) {
        todo.querySelector('.destroy').click();
        break;
      }
    }
  }
}

setWorldConstructor(AppWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app is loaded with no existing todos', async function () {
  await this.loadApp();
});

Given('the user has a todo {string}', async function (title) {
  await this.createTodo(title);
});

Given('the user has a completed todo {string}', async function (title) {
  await this.createCompletedTodo(title);
});

When('the user types {string} in the new todo input and presses Enter', async function (title) {
  const input = this.find('.new-todo');
  input.value = title;
  this.sendEnter(input);
});

When('the user presses Enter with an empty new todo input', async function () {
  const input = this.find('.new-todo');
  input.value = '';
  this.sendEnter(input);
});

When('the user double-clicks the todo {string}', async function (title) {
  const todos = this.findAll('.todo-list li');
  for (const todo of todos) {
    const label = todo.querySelector('label');
    if (label && label.textContent === title) {
      label.dispatchEvent(new this.window.Event('dblclick'));
      break;
    }
  }
});

When('the user changes the edit input to {string} and presses Enter', async function (text) {
