    const editInput = editing.querySelector('.edit');
    editInput.value = text;
    editInput.dispatchEvent(new this.window.Event('blur'));
  }
});

When('the user changes the edit input to {string} and presses Escape', async function (text) {
  const editing = this.find('.todo-list li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    editInput.value = text;
    this.sendEscape(editInput);
  }
});

When('the user clears the edit input and presses Enter', async function () {
  const editing = this.find('.todo-list li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    editInput.value = '';
    editInput.dispatchEvent(new this.window.Event('blur'));
  }
});

When('the user toggles the checkbox for {string}', async function (title) {
