/**
 * TodoMVC application
 * Pure vanilla JavaScript implementation
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';
  var todos = [];
  var currentFilter = 'all';

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      todos = stored ? JSON.parse(stored) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({
      id: generateId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    if (trimmed === '') {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function getFilteredTodos() {
    switch (currentFilter) {
      case 'active':
        return todos.filter(function (t) { return !t.completed; });
      case 'completed':
        return todos.filter(function (t) { return t.completed; });
      default:
        return todos;
    }
  }

  function render() {
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var todoList = document.querySelector('.todo-list');
    var toggleAllCheckbox = document.querySelector('#toggle-all');
    var todoCount = document.querySelector('.todo-count');
    var clearCompletedBtn = document.querySelector('.clear-completed');

    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    todoList.innerHTML = '';
    var filtered = getFilteredTodos();
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var plural = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + plural + ' left';

    toggleAllCheckbox.checked = todos.length > 0 && todos.every(function (t) { return t.completed; });

    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';

    updateFilterLinks();
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  function updateFilterLinks() {
    var links = document.querySelectorAll('.filters a');
    links.forEach(function (link) {
      link.classList.remove('selected');
      var hash = link.getAttribute('href');
      if (hash === '#/' && currentFilter === 'all') link.classList.add('selected');
      else if (hash === '#/active' && currentFilter === 'active') link.classList.add('selected');
      else if (hash === '#/completed' && currentFilter === 'completed') link.classList.add('selected');
    });
  }

  function setupEventListeners() {
    var newTodoInput = document.querySelector('.new-todo');
    var toggleAllCheckbox = document.querySelector('#toggle-all');
    var clearCompletedBtn = document.querySelector('.clear-completed');
    var todoList = document.querySelector('.todo-list');

    newTodoInput.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.keyCode === 13) {
        addTodo(newTodoInput.value);
        newTodoInput.value = '';
      }
    });

    toggleAllCheckbox.addEventListener('change', function () {
      toggleAll();
    });

    clearCompletedBtn.addEventListener('click', function () {
      clearCompleted();
    });

    todoList.addEventListener('click', function (e) {
      var target = e.target;
      var li = target.closest('li');
      if (!li) return;
      var id = li.dataset.id;

      if (target.classList.contains('toggle')) {
        toggleTodo(id);
      } else if (target.classList.contains('destroy')) {
        destroyTodo(id);
      }
    });

    todoList.addEventListener('dblclick', function (e) {
      var target = e.target;
      if (target.tagName !== 'LABEL') return;
      var li = target.closest('li');
      if (!li) return;

      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();

      editInput.addEventListener('blur', function handler() {
        editInput.removeEventListener('blur', handler);
        li.classList.remove('editing');
        editTodo(li.dataset.id, editInput.value);
      });

      editInput.addEventListener('keydown', function handler(ev) {
        if (ev.key === 'Enter' || ev.keyCode === 13) {
          editInput.removeEventListener('blur', handler);
          editInput.removeEventListener('keydown', handler);
          li.classList.remove('editing');
          editTodo(li.dataset.id, editInput.value);
        } else if (ev.key === 'Escape' || ev.keyCode === 27) {
          editInput.removeEventListener('blur', handler);
          editInput.removeEventListener('keydown', handler);
          li.classList.remove('editing');
          editInput.value = li.querySelector('label').textContent;
        }
      });
    });

    window.addEventListener('hashchange', function () {
      handleRoute();
    });

    handleRoute();
  }

  function handleRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') currentFilter = 'active';
    else if (hash === '#/completed') currentFilter = 'completed';
    else currentFilter = 'all';
    render();
  }

  function init() {
    loadTodos();
    setupEventListeners();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

